import type { Artifact, EvalResult, ModelVerdict, SuiteEpoch } from "./types.js";

/**
 * Eval cache keyed by (claimHash, model, promptVersion, suiteEpoch).
 *
 * The fourth component is what makes "every number comparable forever" true rather than
 * aspirational. A prompt change or a model swap always yielded a new key; a **corpus** change did
 * not, because `claimHash` is generated by a literal in `suites.ts` — `smoke-0000` under every
 * version of that file. So re-cutting or relabelling the gold corpus left every old entry still
 * addressable, and `gradeCached` would answer a question about today's exam with a verdict
 * recorded against last week's. `FileEvalCache` persists that across processes, which turns a
 * stale hit from a nuisance into a published number.
 *
 * The epoch is a digest of the artifacts (`suiteEpoch`), so a corpus that has not changed keeps its
 * cache and one that has misses it entirely.
 */
export interface EvalCache {
  get(key: CacheKey): EvalResult | null;
  set(key: CacheKey, result: EvalResult): void;
  has(key: CacheKey): boolean;
  size: number;
}

export interface CacheKey {
  claimHash: string;
  modelId: string;
  promptVersion: string;
  suiteEpoch: SuiteEpoch;
}

export function cacheKey(
  claimHash: string,
  modelId: string,
  promptVersion: string,
  suiteEpoch: SuiteEpoch,
): CacheKey {
  return { claimHash, modelId, promptVersion, suiteEpoch };
}

export function cacheKeyString(key: CacheKey): string {
  return `${key.claimHash}::${key.modelId}::${key.promptVersion}::${key.suiteEpoch}`;
}

/**
 * In-memory eval cache. Persistent deployments swap the backing store; the key shape is shared.
 *
 * "Shared", not "locked": the shape gained `suiteEpoch` when it became clear that a key omitting
 * the corpus asserts something false — that two numbers computed from different exams are the same
 * number. `FileEvalCache` refuses a line whose key it cannot reconstruct from the record, so an
 * entry written by an older shape is counted as corrupt and skipped rather than trusted.
 */
export class MemoryEvalCache implements EvalCache {
  private store = new Map<string, { key: CacheKey; value: EvalResult }>();

  get(key: CacheKey): EvalResult | null {
    return this.store.get(cacheKeyString(key))?.value ?? null;
  }

  set(key: CacheKey, result: EvalResult): void {
    this.store.set(cacheKeyString(key), { key, value: result });
  }

  has(key: CacheKey): boolean {
    return this.store.has(cacheKeyString(key));
  }

  get size(): number {
    return this.store.size;
  }

  clear(): void {
    this.store.clear();
  }

  entries(): IterableIterator<[CacheKey, EvalResult]> {
    const inner = this.store.values()[Symbol.iterator]() as Iterator<{ key: CacheKey; value: EvalResult }>;
    return {
      [Symbol.iterator](): IterableIterator<[CacheKey, EvalResult]> {
        return this;
      },
      next(): IteratorResult<[CacheKey, EvalResult]> {
        const { done, value } = inner.next();
        if (done) return { value: undefined as unknown as [CacheKey, EvalResult], done: true };
        return { value: [value.key, value.value], done: false };
      },
    };
  }
}

/**
 * Grade one more time, whether or not the cache already answers.
 *
 * This is what a retest has to be. `gradeCached` is keyed by
 * `(claimHash, modelId, promptVersion, suiteEpoch)` and deliberately returns the stored verdict, so
 * a loop that re-grades through it gets the same object back twenty times without a single call to
 * the model — a test-retest agreement of exactly 1.0, computed from nothing. Gate 424 measures
 * whether a frontier model wobbles at temperature 0; wobbling is a property of the call, so the
 * draw has to be a call. The result still lands in the cache, because a re-run of a tournament
 * should replay the verdicts it paid for rather than spend again.
 */
export async function gradeFresh(
  cache: EvalCache,
  adapter: { id: string },
  artifact: Artifact,
  promptVersion: string,
  suiteEpoch: SuiteEpoch,
  grade: () => Promise<ModelVerdict>,
): Promise<ModelVerdict & { cached: boolean }> {
  const verdict = await grade();
  cache.set(
    cacheKey(artifact.claimHash, adapter.id, promptVersion, suiteEpoch),
    evalResult(artifact, adapter.id, promptVersion, suiteEpoch, verdict),
  );
  return { ...verdict, cached: false };
}

/** Grade an artifact through a model adapter, honoring the eval cache. */
export async function gradeCached(
  cache: EvalCache,
  adapter: { id: string },
  artifact: Artifact,
  promptVersion: string,
  suiteEpoch: SuiteEpoch,
  grade: () => Promise<ModelVerdict>,
): Promise<ModelVerdict & { cached: boolean }> {
  const key = cacheKey(artifact.claimHash, adapter.id, promptVersion, suiteEpoch);
  const existing = cache.get(key);
  if (existing) {
    return {
      verdict: existing.actual,
      confidence: existing.confidence,
      latencyMs: existing.latencyMs,
      promptVersion,
      cached: true,
    };
  }

  const verdict = await grade();
  cache.set(key, evalResult(artifact, adapter.id, promptVersion, suiteEpoch, verdict));

  return { ...verdict, cached: false };
}

/** One model's verdict on one artifact, as the cache and the scorecard both record it. */
function evalResult(
  artifact: Artifact,
  modelId: string,
  promptVersion: string,
  suiteEpoch: SuiteEpoch,
  verdict: ModelVerdict,
): EvalResult {
  return {
    claimHash: artifact.claimHash,
    modelId,
    promptVersion,
    suite: artifact.suite,
    suiteEpoch,
    expected: artifact.expectedVerdict,
    actual: verdict.verdict,
    confidence: verdict.confidence,
    correct: verdict.verdict === artifact.expectedVerdict,
    falsePass: verdict.verdict === "PASS" && artifact.expectedVerdict !== "PASS",
    falseFail: verdict.verdict !== "PASS" && artifact.expectedVerdict === "PASS",
    latencyMs: verdict.latencyMs,
    killed: false,
    // Carried from the artifact beside `suite`: the scorer splits a row by tier and by safety, and
    // a record that could not say which tier it was earned in could not be profiled after the fact.
    tier: artifact.tier,
    difficulty: artifact.difficulty,
    ...(artifact.safety === true ? { safety: true } : {}),
  };
}
